from flask import Flask, request

app = Flask(__name__)

db = SQL("sqlite:///froshims.db")

@app.route("/register", methods=["POST"])
def register():
    db.execute("INSERT INTO registrants (name, sport) VALUES(?, ?)", request.form.get("name"), request.form.get("sport"))
    return "ok"

@app.route("/count")
def count():
    rows = db.execute("SELECT COUNT(*) AS n FROM registrants WHERE sport = ?", "Soccer")
    return str(rows[0]["n"])

